INSERT INTO `ai_monthly_insights` (`id`, `user_id`, `month`, `summary`, `highlights`, `actions`, `status`, `provider`, `model`, `metadata`, `generated_at`, `created_at`, `updated_at`) VALUES ('10', '3', '2026-09', 'In September 2026, you maintained a positive financial balance of Rs. 47,500.00 (a 73.1% savings rate). Your primary expense driver was Food, accounting for 65.4% of all outflows.', '[\"Dominant Expense: Food represented 65.4% (Rs. 11,450.00) of total monthly spending.\",\"Stable Outflow: Spending remained consistent with past month trends (2.9% variance).\",\"Cash Flow Surplus: Net savings of Rs. 47,500.00 achieved.\"]', '[\"Set a dedicated weekly cap on Food to prevent it from consuming over a third of your monthly allowance.\",\"Monitor categories approaching their limits (Transport) to avoid end-of-month budget breaches.\",\"Allocate at least Rs. 5,000.00 of your surplus directly to your emergency fund or savings goal.\"]', 'ai_generated', 'fallback', 'ai-model', '{\"total_income\":65000,\"total_expense\":17500,\"net_balance\":47500,\"top_category\":\"Food\"}', '2026-09-25 10:37:37', '2026-09-25 10:37:37', '2026-09-25 10:37:37');
